+describe("OpenAIApiErrorSchema", () => {
+  it("accepts optional fields", () => {
+    const parsed = OpenAIApiErrorSchema.parse({
+      error: {
+        message: "invalid request",
+        type: "invalid_request_error",
+      },
+    });
+
+    expect(parsed.error.message).toBe("invalid request");
