+  resetUsage: z.boolean().optional(),
+  limits: z.array(
+    z.object({
+      limitType: z.enum(LIMIT_TYPES),
+      limitWindow: z.enum(LIMIT_WINDOWS),
+      maxValue: z.number(),
+      modelFilter: z.string().nullable().optional(),
+    }),
+  ).optional(),
+}).passthrough();
