+
+type DashboardAccountStatus = "active" | "paused" | "limited" | "exceeded" | "deactivated";
+
+function normalizeStatus(status: string): DashboardAccountStatus {
+  if (status === "paused") {
+    return "paused";
+  }
+  if (status === "rate_limited") {
+    return "limited";
+  }
+  if (status === "quota_exceeded") {
+    return "exceeded";
+  }
+  if (status === "deactivated") {
+    return "deactivated";
+  }
+  return "active";
