+import { useQuery } from "@tanstack/react-query";
+import { z } from "zod";
+
+import { get } from "@/lib/api-client";
+
+const ModelsResponseSchema = z.object({
+  models: z.array(
+    z.object({
+      id: z.string(),
+      name: z.string(),
+    }),
+  ),
